package com.supportsphere.dao;
import com.supportsphere.model.*; import com.supportsphere.util.*; import java.sql.*; import java.time.*; import java.util.*;
public class RequestDAO implements DAO<AssistanceRequest,Integer>{
 public List<AssistanceRequest> findAll()throws Exception{return findAllRequests();}
 public int save(AssistanceRequest r)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO assistance_requests(requester_id,task_type,description,area,city,landmark,urgency,preferred_date,start_time,end_time) VALUES(?,?,?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,r.getRequesterId());p.setString(2,r.getTaskType());p.setString(3,r.getDescription());p.setString(4,r.getArea());p.setString(5,r.getCity());p.setString(6,r.getLandmark());p.setString(7,r.getUrgency().name());p.setDate(8,java.sql.Date.valueOf(r.getPreferredDate()));p.setTime(9,Time.valueOf(r.getStartTime()));p.setTime(10,Time.valueOf(r.getEndTime()));p.executeUpdate();try(ResultSet x=p.getGeneratedKeys()){x.next();int id=x.getInt(1);try(PreparedStatement h=c.prepareStatement("INSERT INTO request_history(request_id,old_status,new_status,changed_by,note) VALUES(?,?,?,?,?)")){h.setInt(1,id);h.setString(2,null);h.setString(3,"OPEN");h.setInt(4,r.getRequesterId());h.setString(5,"Request created");h.executeUpdate();}return id;}}}
 public List<AssistanceRequest> findByRequester(int id)throws Exception{return query("SELECT ar.*,CONCAT(u.name) volunteer_name FROM assistance_requests ar LEFT JOIN assignments a ON a.request_id=ar.request_id LEFT JOIN users u ON u.user_id=a.volunteer_id WHERE ar.requester_id=? ORDER BY ar.created_at DESC",id);}
 public List<AssistanceRequest> findOpen()throws Exception{return query("SELECT ar.*,NULL volunteer_name FROM assistance_requests ar WHERE ar.status='OPEN' AND CONCAT(ar.preferred_date,' ',ar.end_time)>=NOW() ORDER BY FIELD(ar.urgency,'EMERGENCY','HIGH','MEDIUM','LOW'),ar.preferred_date,ar.start_time");}
 public List<AssistanceRequest> findAllRequests()throws Exception{return query("SELECT ar.*,u.name volunteer_name FROM assistance_requests ar LEFT JOIN assignments a ON a.request_id=ar.request_id LEFT JOIN users u ON u.user_id=a.volunteer_id ORDER BY ar.created_at DESC");}
 public Optional<AssistanceRequest> findById(Integer id)throws Exception{List<AssistanceRequest>x=query("SELECT ar.*,u.name volunteer_name FROM assistance_requests ar LEFT JOIN assignments a ON a.request_id=ar.request_id LEFT JOIN users u ON u.user_id=a.volunteer_id WHERE ar.request_id=?",id);return x.stream().findFirst();}
 public void cancel(int id,int userId,String reason)throws Exception{updateStatus(id,"CANCELLED",userId,reason);}
 public void changeStatus(int id,String status,int userId,String note)throws Exception{updateStatus(id,status,userId,note);}
 private void updateStatus(int id,String status,int by,String note)throws Exception{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{String old="";try(PreparedStatement q=c.prepareStatement("SELECT status FROM assistance_requests WHERE request_id=? FOR UPDATE")){q.setInt(1,id);try(ResultSet r=q.executeQuery()){if(!r.next())throw new SQLException("Request not found");old=r.getString(1);}}try(PreparedStatement p=c.prepareStatement("UPDATE assistance_requests SET status=?,cancellation_reason=? WHERE request_id=?")){p.setString(1,status);p.setString(2,note);p.setInt(3,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO request_history(request_id,old_status,new_status,changed_by,note) VALUES(?,?,?,?,?)")){p.setInt(1,id);p.setString(2,old);p.setString(3,status);p.setInt(4,by);p.setString(5,note);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public List<String> history(int id)throws Exception{List<String>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT CONCAT(DATE_FORMAT(created_at,'%d %b %Y %h:%i %p'),' — ',new_status,IF(note IS NULL OR note='', '',CONCAT(' — ',note))) FROM request_history WHERE request_id=? ORDER BY created_at")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())x.add(r.getString(1));}}return x;}
 private List<AssistanceRequest> query(String sql,Object...args)throws Exception{List<AssistanceRequest>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);try(ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));}}return x;}
 private AssistanceRequest map(ResultSet r)throws Exception{AssistanceRequest a=new AssistanceRequest();a.setRequestId(r.getInt("request_id"));a.setRequesterId(r.getInt("requester_id"));a.setTaskType(r.getString("task_type"));a.setDescription(r.getString("description"));a.setArea(r.getString("area"));a.setCity(r.getString("city"));a.setLandmark(r.getString("landmark"));a.setUrgency(Urgency.valueOf(r.getString("urgency")));a.setPreferredDate(r.getDate("preferred_date").toLocalDate());a.setStartTime(r.getTime("start_time").toLocalTime());a.setEndTime(r.getTime("end_time").toLocalTime());a.setStatus(RequestStatus.valueOf(r.getString("status")));a.setCancellationReason(r.getString("cancellation_reason"));a.setVolunteerName(r.getString("volunteer_name"));return a;}
}
